ncontrado"},{"slug":"vera-lucia","sq":"250002536915","volume":2,"outcome":"encontrado"},{"slug":"vera-lucia-ce","sq":"60002553922","volume":1,"outcome":"encontrado"},{"slug":"vicentinho-junior","sq":"270002544544","volume":9,"outcome":"encontrado"},{"slug":"victor-assis","sq":"170002552776","volume":5,"outcome":"encontrado"},{"slug":"vivian-mendes","sq":"250002544912","volume":1,"outcome":"encontrado"},{"slug":"well-macedo","sq":"140002554108","volume":0,"outcome":"indeterminado"},{"slug":"wellington-fagundes","sq":"110002551737","volume":5,"outcome":"encontrado"},{"slug":"wilder-morais","sq":"90002551791","volume":13,"outcome":"encontrado"},{"slug":"william-siri","sq":"190002536162","volume":7,"outcome":"encontrado"},{"slug":"wilson-grassi-junior","sq":"280002548139","volume":9,"outcome":"encontrado"},{"slug":"witer-naves","sq":"270002539187","volume":1,"outcome":"encontrado"},{"slug":"yuri-ezequiel","sq":"150002540204","volume":1,"outcome":"encontrado"},{"slug":"ze-batista","sq":"60002549967","volume":2,"outcome":"encontrado"}]$dataset$::jsonb;
  inserted integer;
BEGIN
  -- O replay PG17 começa vazio, mas migrations antigas deixam uma coorte
  -- parcial. A flag exclusiva do harness evita classificar isso como drift;
  -- sem a flag, inclusive com zero candidatos, o CAS de 513 reprova.
  IF current_setting('pf.replay', true) = 'true' THEN
    RAISE NOTICE 'sites_tse_2026: coleta ignorada no replay descartavel';
    RETURN;
  END IF;
  IF jsonb_array_length(expected) <> 513 OR
     (SELECT count(*) FROM public.candidatos WHERE publicavel IS TRUE) <> 513 OR
     (SELECT count(*)
        FROM jsonb_to_recordset(expected) AS e(slug text,sq text,volume integer,outcome text)
        JOIN public.candidatos c
          ON c.slug=e.slug AND c.sq_candidato_2026=e.sq AND c.publicavel IS TRUE) <> 513 THEN
    RAISE EXCEPTION 'sites_tse_2026: coorte ou SQ divergente do snapshot oficial';
  END IF;
  IF EXISTS (SELECT 1 FROM public.coleta_log WHERE execucao='migration:20260924204852') THEN
    RAISE EXCEPTION 'sites_tse_2026: recibos ja existem';
  END IF;

  -- @write tabela=coleta_log ref=migration:20260924204852 campos=fonte,escopo,alvo,candidato_id,executado_em,resultado,volume,detalhe,url,execucao,natureza
  INSERT INTO public.coleta_log
    (fonte,escopo,alvo,candidato_id,executado_em,resultado,volume,detalhe,url,execucao,natureza)
  SELECT 'sites-tse','candidato',c.slug,c.id,
         '2026-09-24T16:56:50.458Z'::timestamptz,
         e.outcome,
         e.volume,
         jsonb_build_object(
           'ano_eleicao',2026,
           'sq_candidato',e.sq,
           'escopo','recurso integral de redes sociais do TSE, unido por SQ/UF/cargo',
           'resource_sha256','88f3168f4fe8f1758c9153b548c7194dfe37aa76f5e08eb7acd731dbf31ac176',
           'snapshot','candidate-sites-tse-2026.json',
            'motivo',CASE WHEN e.outcome='indeterminado' THEN 'entrada sem URL publicavel' ELSE 'URL publicavel ou vazio no escopo' END
         )::text,
         'https://cdn.tse.jus.br/estatistica/sead/odsele/consulta_cand/rede_social_candidato_2026.zip',
         'migration:20260924204852','coleta'
  FROM jsonb_to_recordset(expected) AS e(slug text,sq text,volume integer,outcome text)
  JOIN public.candidatos c ON c.slug=e.slug AND c.sq_candidato_2026=e.sq
  ORDER BY c.slug;
  GET DIAGNOSTICS inserted = ROW_COUNT;
  IF inserted <> 513 THEN RAISE EXCEPTION 'sites_tse_2026: recibos escritos %, esperado 513',inserted; END IF;
END
$migration$;

COMMIT;
